export async function operationProofV57(M,entry,op,role,h){if(!names.includes(entry.raw.name)||!JSON.stringify(op).includes('v57')&&!op.kind?.startsWith('spell-')&&op.kind!=='gift-spell-v21')return null;let count=0;const assert=Object.fromEntries(['ok','equal','deepEqual'].map(k=>[k,(...args)=>{count++;strict[k](...args);} ]));for(const positive of[true,false])await proveCommonV57(M,entry.raw.name,role,positive,h,assert);return count;}
